/* CodeVenjar AI - database-backed browser app.
   Works in demo mode until Supabase URL + anon key are added to supabase-config.js. */
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const configured = Boolean(window.supabase && window.CODEVANJAR_SUPABASE_URL && window.CODEVANJAR_SUPABASE_ANON_KEY);
const db = configured ? window.supabase.createClient(window.CODEVANJAR_SUPABASE_URL, window.CODEVANJAR_SUPABASE_ANON_KEY) : null;
const app = document.querySelector('#app');
const nav = [['overview','⌂','Overview'],['assessment','◈','Skill assessment'],['roadmap','↗','My roadmap'],['assignments','✓','Assignments'],['courses','▤','Courses'],['records','▥','My records'],['status','●','Current status'],['ai','✦','AI support'],['mentors','♧','Mentors'],['portfolio','▣','Portfolio']];
const templates = {
  'Data Analyst': { skills:['Excel','SQL','Python','Storytelling'], projects:[['Retail Sales Dashboard','SQL · Power BI','3–4 hours'],['Customer Churn Story','Python · SQL','5–6 hours'],['Marketing Performance Report','Excel · Storytelling','4 hours']] },
  'Web Developer': { skills:['HTML/CSS','JavaScript','React','Git'], projects:[['Responsive Portfolio','HTML/CSS · Git','3–4 hours'],['Full-stack Task Board','React · API','6–8 hours'],['E-commerce Product Page','React · GitHub','5 hours']] },
  'AI Engineer': { skills:['Python','Math & Statistics','Machine Learning','LLM APIs'], projects:[['Student Score Predictor','Python · ML','4–5 hours'],['RAG Study Assistant','Python · LLM API','6–8 hours'],['Resume Feedback Agent','Prompting · API','5 hours']] }
};
const catalog = [
  {id:'excel-starter',title:'Excel Starter for Career Beginners',mode:'Recorded',level:'Beginner',duration:'2 weeks',price:0,description:'Cells, formulas, sorting, filters and a career-ready mini dashboard.',skills:['Excel','Data basics'],outcome:'Complete your first mini dashboard.',notes:['Excel formulas cheat sheet','Practice sales dataset','Dashboard checklist'],access:'Instant recorded access'},
  {id:'sql-foundations',title:'SQL Foundations for Analysts',mode:'Live',level:'Beginner',duration:'4 weeks',price:499,description:'Queries, joins, filtering, aggregation and interview datasets.',skills:['SQL','Data cleaning'],outcome:'Complete 20 practical SQL challenges.',notes:['SQL joins notes','Weekly query workbook','Live class recordings'],access:'Tuesday and Thursday, 7:00 PM IST'},
  {id:'power-bi',title:'Power BI Business Dashboard',mode:'Live',level:'Intermediate',duration:'3 weeks',price:799,description:'Turn business data into an interactive dashboard and clear insights.',skills:['Power BI','Storytelling'],outcome:'Publish one portfolio-ready executive dashboard.',notes:['Dashboard wireframe','DAX quick reference','Business storytelling notes'],access:'Saturday, 11:00 AM IST'},
  {id:'python-data',title:'Python for Data Projects',mode:'Recorded',level:'Intermediate',duration:'6 weeks',price:999,description:'Pandas, visualisation, notebooks and a complete analytics project.',skills:['Python','Pandas'],outcome:'Ship a reproducible Python case study.',notes:['Pandas notebook','Cleaning checklist','Project rubric'],access:'Instant recorded access'},
  {id:'web-starter',title:'Web Developer Starter Track',mode:'Recorded',level:'Beginner',duration:'6 weeks',price:899,description:'HTML, CSS, JavaScript, Git and a responsive portfolio website.',skills:['HTML/CSS','JavaScript','Git'],outcome:'Deploy a polished personal portfolio.',notes:['HTML/CSS reference','Git commands sheet','Portfolio checklist'],access:'Instant recorded access'}
];
const fallbackMentors = [
  {id:'m1',name:'Neha Sharma',role:'Senior Data Analyst',specialty:'SQL · Power BI · Interviews',rating:4.9,availability:'Tue & Thu · 7:00 PM',bio:'Helps students turn dashboards into strong portfolio stories.'},
  {id:'m2',name:'Arjun Mehta',role:'Analytics Engineer',specialty:'Python · Data Projects',rating:4.8,availability:'Wed · 8:00 PM',bio:'Guides beginners through practical Python and case-study projects.'},
  {id:'m3',name:'Riya Kapoor',role:'Career Coach',specialty:'Resume · LinkedIn · Mock interviews',rating:4.9,availability:'Sat · 11:00 AM',bio:'Helps learners present their skills clearly to internship recruiters.'}
];
const fallbackAssignments = [
  {id:'a1',title:'SQL Gap Check',topic:'SQL',difficulty:'Beginner',estimated_minutes:20,prompt:'Write a query that returns total sales by product category using GROUP BY.',answer_hint:'Use SELECT category, SUM(sales) and GROUP BY category.'},
  {id:'a2',title:'Dashboard Insight',topic:'Storytelling',difficulty:'Beginner',estimated_minutes:15,prompt:'Write two business insights from a dashboard showing falling sales and rising returns.',answer_hint:'Mention the trend, evidence and one recommended action.'},
  {id:'a3',title:'Python Data Cleaning',topic:'Python',difficulty:'Intermediate',estimated_minutes:30,prompt:'List three steps you would take before analysing a CSV with missing values.',answer_hint:'Profile missingness, choose an imputation/drop strategy and validate the cleaned data.'}
];
const state = {page:'overview',goal:'Data Analyst',hours:'3–5 hours',project:'',skills:{Excel:78,SQL:55,Python:42,Storytelling:64},journey:42,plan:null,status:'Learning',records:[],enrollments:[],payments:[],bookings:[],selectedCourse:null,selectedNotes:null,selectedMentor:null,portfolio:null,aiMessages:[],courses:catalog,mentors:fallbackMentors,assignments:fallbackAssignments,user:null,session:null,ready:false,isAdmin:false,demo:!configured};
const key = 'codevenjar-demo-profile';
try { Object.assign(state, JSON.parse(localStorage.getItem(key) || '{}')); } catch (_) {}
const demoAuthKey = 'codevenjar-demo-auth';
let demoAuth = {};
try { demoAuth = JSON.parse(localStorage.getItem(demoAuthKey) || '{}'); } catch (_) {}
function saveDemoAuth(){ localStorage.setItem(demoAuthKey, JSON.stringify(demoAuth)); }

function saveDemo(){ if(state.demo) localStorage.setItem(key, JSON.stringify({...state,user:null,session:null})); }
function now(){return new Date().toISOString()}
function planFor(goal=state.goal,skills=state.skills,hours=state.hours,project=state.project){const t=templates[goal]||templates['Data Analyst'];const ordered=t.skills.map(k=>[k,Number(skills[k]??0)]).sort((a,b)=>a[1]-b[1]);const gaps=ordered.filter(x=>x[1]<70);const focus=gaps.length?gaps.slice(0,3).map(x=>x[0]):[ordered[0]?.[0]||t.skills[0]];const multiplier=hours==='10+ hours'?1.7:hours==='6–10 hours'?1.3:1;const weeks=Math.max(4,Math.round(8/multiplier));return {goal,hours,project,focus,weeks,items:[['Foundation & gap repair',`Learn ${focus[0]} through a focused module`,`${Math.min(100,Math.round((100-(ordered[0]?.[1]||0))*0.8))}% gap`],['Guided practice',`Complete 3 ${focus.slice(0,2).join(' + ')} challenges`,`${Math.max(2,Math.round(weeks/3))} weeks`],['Build your project',project?`Build: ${project}`:`Ship a ${goal} portfolio project`,hours],['Portfolio & proof','Write a case study, publish your work and prepare an interview story','Job-ready']],projects:t.projects,createdAt:now()}}
function courseById(id){return state.courses.find(c=>c.id===id)||catalog.find(c=>c.id===id)}
function userId(){return state.profile?.learner_id || (state.user?.id ? `CV-${state.user.id.slice(0,8).toUpperCase()}` : 'CV-DEMO-USER')}
async function logEvent(type,title,detail=''){const record={record_type:type,title,detail,created_at:now(),learner_id:userId()};state.records.unshift(record);state.records=state.records.slice(0,100);saveDemo();if(db&&state.user){const [activity,recordInsert]=await Promise.all([db.from('activity_events').insert({user_id:state.user.id,event_type:type,event_name:title,metadata:{detail,learner_id:userId()}}),db.from('learner_records').insert({user_id:state.user.id,learner_id:userId(),record_type:type,title,detail})]);if(activity.error) console.warn('Activity log failed',activity.error.message);if(recordInsert.error) console.warn('Record save failed',recordInsert.error.message);}}
async function loadData(){if(!db||!state.user)return;const uid=state.user.id;const [p,s,r,e,b,port,c,m,a] = await Promise.all([db.from('profiles').select('*').eq('id',uid).maybeSingle(),db.from('skills').select('*').eq('user_id',uid),db.from('learner_records').select('*').eq('user_id',uid).order('created_at',{ascending:false}).limit(100),db.from('enrollments').select('*,course_catalog(*)').eq('user_id',uid).order('enrolled_at',{ascending:false}),db.from('mentor_bookings').select('*,mentors(*)').eq('user_id',uid).order('created_at',{ascending:false}),db.from('portfolio_profiles').select('*').eq('user_id',uid).maybeSingle(),db.from('course_catalog').select('*').eq('is_active',true).order('created_at'),db.from('mentors').select('*').eq('is_active',true),db.from('assignments').select('*').order('id')]);
 state.profile=p.data||{id:uid,learner_id:userId(),full_name:state.user.user_metadata?.full_name||state.user.email?.split('@')[0]||'Learner'};state.goal=state.profile.target_role||state.goal;state.skills=Object.fromEntries((s.data||[]).map(x=>[x.skill_name,x.confidence]));state.records=r.data||[];state.enrollments=(e.data||[]).map(x=>({...x,title:x.course_catalog?.title||x.course_id,transactionId:x.id}));state.bookings=(b.data||[]).map(x=>({...x,mentor:x.mentors?.name||x.mentor_id,slot:x.slot}));state.portfolio=port.data;state.courses=c.data?.length?c.data.map(x=>({...x,price:x.price_inr,mode:x.delivery_mode,access:x.access_details})):catalog;state.mentors=m.data?.length?m.data: fallbackMentors;state.assignments=a.data?.length?a.data:fallbackAssignments;state.plan=state.profile.roadmap||planFor();
 const admin=await db.from('admin_users').select('user_id').eq('user_id',uid).maybeSingle();state.isAdmin=Boolean(admin.data);state.ready=true;render();}
 async function saveAssessment(goal,hours,skills,project){state.goal=goal;state.hours=hours;state.project=project;state.skills=skills;state.plan=planFor(goal,skills,hours,project);state.status='Learning';if(db&&state.user){await db.from('profiles').upsert({id:state.user.id,learner_id:userId(),full_name:state.profile?.full_name||state.user.email,target_role:goal,roadmap:state.plan,updated_at:now()});await db.from('skills').delete().eq('user_id',state.user.id);await db.from('skills').insert(Object.entries(skills).map(([skill_name,confidence])=>({user_id:state.user.id,skill_name,confidence})));}await logEvent('Assessment','Skill assessment updated',`${goal} · ${hours}`);saveDemo();}
 function header(kicker,title,subtitle,action=''){return `<div class="topbar"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${subtitle}</p></div><div class="top-actions">${action}</div></div>`}
 function authPage(){return `<div class="auth-wrap"><div class="card auth-card"><div class="brand auth-brand"><div class="mark">CV</div><div><strong>CodeVenjar AI</strong><small>Career copilot</small></div></div><span class="pill">BUILD · LEARN · LEAD · IMPACT</span><h1>Turn your skills into a job-ready plan.</h1><p class="auth-copy">Create an account to save your assessment, roadmap, course enrollments, mentor bookings and learning activity.</p><form id="auth-form" class="form-grid"><div class="field full"><label>Email</label><input id="auth-email" type="email" placeholder="you@example.com" required /></div><div class="field full"><label>Password</label><input id="auth-password" type="password" minlength="6" placeholder="Minimum 6 characters" required /></div><div class="field full"><label>Full name (required for sign up)</label><input id="auth-name" placeholder="Your name" /></div><div class="field full auth-actions"><button class="primary" type="submit" data-auth-action="login">Log in</button><button class="secondary" type="button" data-auth-action="signup">Create account</button></div></form><button class="link" id="demo-mode">Continue in demo mode</button><div id="auth-message" class="result hidden"></div></div></div>`}
 function shell(content){app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="mark">CV</div><div><strong>CodeVenjar</strong><small>AI career copilot</small></div></div><nav class="nav">${nav.map(n=>`<button class="${state.page===n[0]?'active':''}" data-page="${n[0]}">${n[1]}&nbsp;&nbsp;${n[2]}</button>`).join('')}${state.isAdmin?'<button class="admin-link" data-page="admin">▦&nbsp;&nbsp;Admin activity</button>':''}</nav><div class="profile-mini"><div class="mini-row"><div class="avatar">${esc((state.profile?.full_name||'Learner').split(' ').map(x=>x[0]).join('').slice(0,2))}</div><div><strong>${esc(state.profile?.full_name||'Learner')}</strong><small style="display:block;color:var(--muted)">${esc(state.status)} · ${esc(userId())}</small></div></div><p>Keep building. Your next opportunity is one project away.</p>${state.demo?'<span class="tag demo-badge">Demo mode</span>':'<button class="link" id="logout">Sign out</button>'}</div></aside><main class="main">${content}</main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()});const out=document.querySelector('#logout');if(out)out.onclick=async()=>{await db.auth.signOut();state.user=null;state.session=null;state.ready=false;render()}}
 function overview(){const p=state.plan||planFor();return header(new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase(),`Good ${new Date().getHours()<12?'morning':'afternoon'}, ${state.profile?.full_name?.split(' ')[0]||'Abhi'}.`,`Live time: <span id="live-time"></span> · Your data is ${state.demo?'in demo mode':'saved in Supabase'}.`,`<button class="secondary" data-page="assessment">Update my skills</button>`)+`<section class="grid hero-grid"><div class="card hero"><span class="pill">✦ AI CAREER CO-PILOT</span><h2>From beginner to job-ready, one clear step at a time.</h2><p>Your ${esc(state.goal)} journey is based on your current skills, available time and target project.</p><button class="primary" data-page="roadmap">Continue journey →</button></div><div class="card goal-card"><div><span class="eyebrow">Current target</span><h3>${esc(state.goal)}</h3><p>Priority gaps: ${esc(p.focus.join(', '))}</p></div><div><div class="progress-ring" style="background:conic-gradient(var(--mint) 0 ${state.journey}%,#1c3947 ${state.journey}%);--progress:${state.journey}%"></div><div style="text-align:center;color:var(--muted);font-size:13px">Journey progress</div></div></div></section><section class="grid stats">${[['Skills mapped',Object.keys(state.skills).length,'Saved profile'],['Weekly time',state.hours,'Your availability'],['Enrollments',state.enrollments.length,'Courses joined'],['Records',state.records.length,'Activity history']].map(x=>`<div class="card stat"><span class="label">${x[0]}</span><strong>${x[1]}</strong><span class="delta">${x[2]}</span></div>`).join('')}</section><section class="grid content-grid"><div class="card"><div class="card-heading"><h3>Your skill snapshot</h3><button class="link" data-page="assessment">Edit skills</button></div><div class="skills">${Object.entries(state.skills).map(([k,v])=>`<div class="skill-row"><span>${esc(k)}</span><div class="bar"><i style="width:${Number(v)}%"></i></div><b>${Number(v)}</b></div>`).join('')}</div></div><div class="card"><div class="card-heading"><h3>This week’s focus</h3><span class="tag">${p.focus.length} gaps</span></div>${p.focus.slice(0,3).map((x,i)=>`<div class="task"><div><p>${i?'Practice':'Start'} ${esc(x)}</p><small>${i?'30':'25'} min · Priority gap</small></div><button class="icon-btn task-done">✓</button></div>`).join('')}</div></section>`}
 function assessment(){const t=templates[state.goal]||templates['Data Analyst'];return header('Personalize your path','Skill assessment','Your answers control the roadmap. Change them anytime to regenerate a better plan.')+`<div class="card form-card"><form id="assessment-form" class="form-grid"><div class="field"><label>Target career</label><select id="goal">${Object.keys(templates).map(g=>`<option ${state.goal===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label>Hours available per week</label><select id="hours"><option ${state.hours==='3–5 hours'?'selected':''}>3–5 hours</option><option ${state.hours==='6–10 hours'?'selected':''}>6–10 hours</option><option ${state.hours==='10+ hours'?'selected':''}>10+ hours</option></select></div>${t.skills.map(k=>`<div class="field"><label>${esc(k)} confidence (0–100)</label><input type="number" min="0" max="100" value="${state.skills[k]??50}" data-skill="${esc(k)}" required /></div>`).join('')}<div class="field full"><label>What do you want to build?</label><textarea id="project" rows="3" placeholder="Example: an internship-ready sales analytics dashboard">${esc(state.project)}</textarea></div><div class="field full"><button class="primary" type="submit">Generate my personalized roadmap ✦</button></div></form><div id="assessment-result" class="result hidden"></div></div>`}
 function roadmapPage(){const p=state.plan||planFor();return header('Your next best steps','My roadmap',`Generated for ${esc(p.goal)} · ${esc(p.hours)} · ${p.weeks}-week journey`,`<button class="primary" data-page="assessment">Regenerate roadmap</button>`)+`<div class="grid content-grid"><div class="card"><div class="card-heading"><h3>${esc(p.goal)} journey</h3><span class="pill">Personalized</span></div><p class="muted-copy">This roadmap begins with your lowest-scoring skills (<strong>${esc(p.focus.join(', '))}</strong>), fits your weekly availability and ends with proof you can show recruiters.</p><div class="roadmap">${p.items.map((r,i)=>`<div class="roadmap-item"><div class="check ${i?'pending':''}">${i?'○':'✓'}</div><div><strong>Week ${i+1}: ${esc(r[0])}</strong><small>${esc(r[1])}</small><small><strong>Why it matters:</strong> ${i===0?'It closes your biggest skill gap.':i===1?'Practice converts lessons into repeatable ability.':i===2?'A shipped project becomes proof of work.':'A case study helps recruiters understand your impact.'}</small></div><span class="tag">${esc(r[2])}</span></div>`).join('')}</div></div><div class="card"><div class="card-heading"><h3>Recommended projects</h3></div>${p.projects.map(x=>`<div class="task"><div><p>${esc(x[0])}</p><small>${esc(x[1])}</small></div><span class="tag">${esc(x[2])}</span></div>`).join('')}<button class="secondary" data-page="assignments" style="margin-top:14px">Open related assignments →</button></div></div>`}
 function assignmentsPage(){return header('Practice to prove','Assignments','Small practical tasks connected to your roadmap. Complete them to build your record.')+`<div class="grid content-grid"><div class="grid">${state.assignments.map(a=>`<div class="card"><div class="card-heading"><h3>${esc(a.title)}</h3><span class="tag">${a.estimated_minutes} min</span></div><p class="muted-copy">${esc(a.prompt)}</p><div class="tag">${esc(a.topic)} · ${esc(a.difficulty)}</div><div class="result"><strong>Hint:</strong> ${esc(a.answer_hint||'Break the problem into small, testable steps.')}</div><button class="primary assignment-done" data-assignment="${esc(a.id)}">Mark assignment complete</button></div>`).join('')}</div><div class="card"><h3>How assignments help</h3><p class="muted-copy">Each submission creates an activity record and shows whether you are moving from learning to practical proof.</p><button class="secondary" data-page="records">View records</button></div></div>`}
 function coursesPage(){return header('Learn and grow','Course marketplace','Live classes, recorded courses and notes/resources in one place.')+`<div class="grid content-grid"><div class="grid">${state.courses.map(c=>`<div class="card"><div class="card-heading"><h3>${esc(c.title)}</h3><span class="tag">${c.price===0?'FREE':'₹'+c.price}</span></div><div class="course-meta"><span class="pill">${esc(c.mode||c.delivery_mode)}</span><span class="tag">${esc(c.level)}</span><span class="tag">${esc(c.duration)}</span></div><p class="muted-copy">${esc(c.description)}</p><p><strong>Access:</strong> <span class="muted-copy">${esc(c.access||c.access_details)}</span></p><div class="course-meta">${(c.skills||[]).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><small class="muted-copy">Notes available · Certificate included</small><div><button class="secondary course-notes" data-course="${esc(c.id)}">View notes</button> <button class="primary course-buy" data-course="${esc(c.id)}">${c.price===0?'Enroll free':'Buy and enroll'} →</button></div></div>`).join('')}</div><div class="card"><div class="card-heading"><h3>My enrollments</h3><span class="tag">${state.enrollments.length}</span></div>${state.enrollments.length?state.enrollments.map(e=>`<div class="task"><div><p>${esc(e.title)}</p><small>${esc(e.status)} · ${esc(e.transactionId||e.id)}</small></div><span class="tag">${e.progress||0}%</span></div>`).join(''):'<p class="muted-copy">No enrollment yet.</p>'}</div></div>${state.selectedCourse?paymentModal(courseById(state.selectedCourse)):''}${state.selectedNotes?notesModal(courseById(state.selectedNotes)):''}`}
 function notesModal(c){return `<div class="modal-backdrop"><div class="card payment-modal"><div class="card-heading"><h3>${esc(c.title)} · Notes</h3><button class="icon-btn" id="close-notes">×</button></div><p class="muted-copy">${esc(c.mode||c.delivery_mode)} course · ${esc(c.access||c.access_details)}</p><div class="roadmap">${(c.notes||[]).map((n,i)=>`<div class="roadmap-item"><div class="check">${i+1}</div><div><strong>${esc(n)}</strong><small>Learning resource</small></div><span class="tag">Notes</span></div>`).join('')}</div><button class="primary" id="save-notes" style="margin-top:16px">Save notes to my records</button></div></div>`}
 function paymentModal(c){return `<div class="modal-backdrop"><div class="card payment-modal"><div class="card-heading"><h3>${c.price===0?'Free enrollment':'Buy & enroll'}: ${esc(c.title)}</h3><button class="icon-btn" id="close-payment">×</button></div><div class="course-meta"><span class="pill">${esc(c.mode||c.delivery_mode)}</span><span class="tag">${esc(c.access||c.access_details)}</span></div><p class="muted-copy">${esc(c.outcome)}</p><div class="result"><strong>${c.price===0?'No payment required':'Total payable: ₹'+c.price}</strong><br/>${c.price===0?'Start learning immediately.':'Choose UPI, debit/credit card or net banking below.'}</div><form id="payment-form" class="form-grid">${c.price===0?'':`<div class="field full"><label>Payment method</label><select id="payment-method"><option>UPI</option><option>Debit/Credit Card</option><option>Net Banking</option></select></div><div class="field full"><label>UPI ID / payment reference</label><input id="payment-reference" placeholder="example@upi or reference number" required /></div>`}<div class="field full"><button class="primary" type="submit">${c.price===0?'Enroll free':'Continue to payment and enroll'}</button></div></form><small class="muted-copy">${c.price===0?'Free enrollment is active.':'This records a pending/demo transaction. For real settlement, connect Razorpay server functions using the setup below.'}</small></div></div>`}
 function mentorsPage(){return header('Connect & grow','Mentor network','Choose a mentor, see availability and book an office hour.')+`<div class="grid content-grid"><div class="grid">${state.mentors.map(m=>`<div class="card"><div class="card-heading"><h3>${esc(m.name)}</h3><span class="pill">★ ${esc(m.rating)}</span></div><strong>${esc(m.role)}</strong><p class="muted-copy">${esc(m.bio)}</p><div class="course-meta"><span class="tag">${esc(m.specialty)}</span><span class="tag">${esc(m.availability||m.slots)}</span></div><button class="primary mentor-book" data-mentor="${esc(m.id)}">Book mentor session →</button></div>`).join('')}</div><div class="card"><h3>My bookings</h3>${state.bookings.length?state.bookings.map(b=>`<div class="task"><div><p>${esc(b.mentor||b.mentors?.name)}</p><small>${esc(b.slot)} · ${esc(b.status)}</small></div><span class="tag">Booked</span></div>`).join(''):'<p class="muted-copy">Choose a mentor to create your first booking.</p>'}</div></div>${state.selectedMentor?mentorModal(state.mentors.find(m=>m.id===state.selectedMentor)):''}`}
 function mentorModal(m){return `<div class="modal-backdrop"><div class="card payment-modal"><div class="card-heading"><h3>Book ${esc(m.name)}</h3><button class="icon-btn" id="close-mentor">×</button></div><p class="muted-copy">${esc(m.role)} · ${esc(m.specialty)}</p><form id="mentor-form" class="form-grid"><div class="field full"><label>Choose a slot</label><select id="mentor-slot"><option>${esc(m.availability||m.slots)}</option><option>Next available slot</option></select></div><div class="field full"><label>What do you need help with?</label><textarea id="mentor-note" rows="3" placeholder="Example: review my SQL dashboard project"></textarea></div><div class="field full"><button class="primary" type="submit">Confirm mentor booking</button></div></form></div></div>`}
