function roleAuthPage(){return `<div class="auth-wrap"><div class="card auth-card"><div class="brand auth-brand"><div class="mark">CV</div><div><strong>CodeVenjar AI</strong><small>Career copilot</small></div></div><span class="pill">PUBLIC ACCESS · CANDIDATE · EMPLOYER</span><h1>Build your career identity.</h1><p class="auth-copy">Log in or create your CodeVenjar ID. Candidates manage learning; employers can explore the public platform without seeing private learner records.</p><form id="auth-form" class="form-grid"><div class="field full"><label>Email</label><input id="auth-email" type="email" placeholder="you@example.com" required /></div><div class="field full"><label>Password</label><input id="auth-password" type="password" minlength="6" placeholder="Minimum 6 characters" required /></div><div class="field full"><label>Full name (required for Create ID)</label><input id="auth-name" placeholder="Your name" /></div><div class="field full"><label>Access type</label><select id="auth-role"><option value="candidate">Candidate / Learner</option><option value="employer">Employer / Recruiter</option></select></div><div class="field full auth-actions"><button class="primary" type="submit" data-auth-action="login">Log in</button><button class="secondary" type="button" data-auth-action="signup">Create CodeVenjar ID</button></div></form><button class="link" id="demo-mode">Continue with local demo</button><div id="auth-message" class="result hidden"></div></div></div>`}
