wireAuth=function(){const form=document.querySelector('#auth-form');if(!form)return;document.querySelectorAll('[data-auth-action]').forEach(b=>b.onclick=()=>form.dataset.action=b.dataset.authAction);form.onsubmit=async e=>{e.preventDefault();const action=form.dataset.action||'login',email=document.querySelector('#auth-email').value.trim(),password=document.querySelector('#auth-password').value,name=document.querySelector('#auth-name').value.trim(),role=document.querySelector('#auth-role').value,msg=document.querySelector('#auth-message');msg.classList.remove('hidden');if(!db){if(action==='login'&&!name){msg.textContent='For local demo login, enter your name. For real login, add Supabase URL and anon key.';return}const learnerId=`CV-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;state.demo=true;state.ready=true;state.role=role;state.profile={full_name:name||email.split('@')[0]||'Demo User',email,role,learner_id:learnerId};state.plan=state.plan||planFor();saveDemo();render();return}msg.textContent='Connecting…';const result=action==='signup'?await db.auth.signUp({email,password,options:{data:{full_name:name,role}}}):await db.auth.signInWithPassword({email,password});if(result.error){msg.textContent=result.error.message;return}if(result.data.session){state.session=result.data.session;state.user=result.data.user;state.role=role;await db.from('profiles').upsert({id:state.user.id,full_name:name||email.split('@')[0],role,learner_id:userId()});await loadData();await logEvent(action==='signup'?'Create ID':'Login','User logged in',`${email} · ${role}`)}else msg.textContent='Account created. Confirm your email, then log in.'};document.querySelector('#demo-mode').onclick=()=>{const name=document.querySelector('#auth-name').value.trim()||'Demo User',email=document.querySelector('#auth-email').value.trim()||'demo@codevenjar.local',role=document.querySelector('#auth-role').value;state.demo=true;state.ready=true;state.role=role;state.profile={full_name:name,email,role,learner_id:`CV-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`};state.plan=state.plan||planFor();saveDemo();render()}}
/* Reliable auth controls: handle button clicks directly so native form validation
   cannot silently block Create ID in local demo mode. */
wireAuth=function(){
  const form=document.querySelector('#auth-form');
  if(!form)return;
  const emailEl=document.querySelector('#auth-email');
  const passwordEl=document.querySelector('#auth-password');
  const nameEl=document.querySelector('#auth-name');
  const roleEl=document.querySelector('#auth-role');
  const msg=document.querySelector('#auth-message');
  const show=(text,ok=false)=>{msg.classList.remove('hidden');msg.innerHTML=ok?`<strong>${esc(text)}</strong>`:esc(text)};
  const goDemo=(email,password,name,role,action)=>{
    const cleanEmail=email.trim(),cleanName=name.trim();
    if(!cleanEmail){show(action==='signup'?'Email is required to create your ID.':'Enter the email used for your ID.');emailEl.focus();return;}
    if(password.length<6){show('Password must contain at least 6 characters.');passwordEl.focus();return;}
    if(action==='signup'){
      if(!cleanName){show('Full name is required to create your ID.');nameEl.focus();return;}
      if(demoAuth[cleanEmail.toLowerCase()]){show('This demo ID already exists. Use Log in, or create it with another email.');return;}
      const learnerId=`CV-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;
      demoAuth[cleanEmail.toLowerCase()]={email:cleanEmail,password,name:cleanName,role,learnerId};saveDemoAuth();
      state.profile={full_name:cleanName,email:cleanEmail,role,learner_id:learnerId};
      show('CodeVenjar ID created. Now click Log in with the same email and password.',true);
      toast('CodeVenjar ID created successfully');
      return;
    }else{
      const account=demoAuth[cleanEmail.toLowerCase()];
      if(!account||account.password!==password){show('Invalid email or password. Create your CodeVenjar ID first.');return;}
      state.profile={full_name:account.name,email:account.email,role:account.role,learner_id:account.learnerId};
    }
    state.demo=true;state.ready=true;state.role=state.profile.role;state.plan=state.plan||planFor();saveDemo();
    toast(action==='signup'?'CodeVenjar ID created successfully':'Login successful');render();
  };
  const submit=async(action)=>{
    const email=emailEl.value.trim(),password=passwordEl.value,name=nameEl.value.trim(),role=roleEl?.value||'candidate';
    if(!db){
      goDemo(email,password,name,role,action);return;
    }
    if(!email){show('Enter your email.');emailEl.focus();return;}
    if(password.length<6){show('Password must contain at least 6 characters.');passwordEl.focus();return;}
    if(action==='signup'&&!name){show('Enter your full name to create an ID.');nameEl.focus();return;}
    show('Connecting…');
    const result=action==='signup'
      ?await db.auth.signUp({email,password,options:{data:{full_name:name,role}}})
      :await db.auth.signInWithPassword({email,password});
    if(result.error){show(result.error.message);return;}
    if(result.data.session){
      state.session=result.data.session;state.user=result.data.user;state.role=role;
      await db.from('profiles').upsert({id:state.user.id,full_name:name||email.split('@')[0],role,learner_id:userId()});
      await loadData();await logEvent(action==='signup'?'Create ID':'Login','User logged in',`${email} · ${role}`);
    }else show('Account created. Check your email confirmation, then use Log in.',true);
  };
  document.querySelectorAll('[data-auth-action]').forEach(button=>button.onclick=event=>{
    event.preventDefault();submit(button.dataset.authAction);
  });
  form.onsubmit=event=>{event.preventDefault();submit('login');};
  const demo=document.querySelector('#demo-mode');
  if(demo)demo.onclick=()=>goDemo(emailEl.value.trim(),passwordEl.value,nameEl.value.trim(),roleEl?.value||'candidate','signup');
};
boot();
if(!configured){setTimeout(()=>{state.demo=false;render();const message=document.querySelector('#auth-message');if(message){message.classList.remove('hidden');message.innerHTML='<strong>Database not connected.</strong><br/>For real-time login and records, create a project at <a href="https://supabase.com/dashboard" target="_blank" rel="noopener">Supabase Dashboard</a>, run <code>supabase/schema.sql</code>, then add the URL and anon key to <code>supabase-config.js</code>.';}},0)}
/* Simple two-option authentication screen: Login or Create ID. */
function codevenjarAuthPage(){return `<div class="auth-wrap"><div class="card auth-card"><div class="brand auth-brand"><div class="mark">CV</div><div><strong>CodeVenjar</strong><small>AI career platform</small></div></div><span class="pill">PUBLIC ACCESS · CANDIDATE · EMPLOYER</span><h1 id="auth-title">Login to CodeVenjar</h1><p class="auth-copy">Use your existing CodeVenjar ID, or create a new one in seconds.</p><div class="auth-choice"><button type="button" class="primary" id="mode-login">Login</button><button type="button" class="secondary" id="mode-signup">Create ID</button></div><form id="auth-form" class="form-grid"><div class="field full"><label>Email</label><input id="auth-email" type="email" placeholder="you@example.com" required /></div><div class="field full"><label>Password</label><input id="auth-password" type="password" minlength="6" placeholder="Minimum 6 characters" required /></div><div class="field full hidden" id="auth-name-field"><label>Full name</label><input id="auth-name" placeholder="Your full name" /></div><div class="field full hidden" id="auth-role-field"><label>Account type</label><select id="auth-role"><option value="candidate">Candidate / Learner</option><option value="employer">Employer</option></select></div><div class="field full"><button class="primary" id="auth-submit" type="submit">Login</button></div></form><button class="link" id="demo-mode">Use local demo</button><div id="auth-message" class="result hidden"></div></div></div>`}
authPage=codevenjarAuthPage;
wireAuth=function(){
  const form=document.querySelector('#auth-form');if(!form)return;
  let mode='login';
  const title=document.querySelector('#auth-title'),nameField=document.querySelector('#auth-name-field'),roleField=document.querySelector('#auth-role-field'),submitButton=document.querySelector('#auth-submit'),loginButton=document.querySelector('#mode-login'),signupButton=document.querySelector('#mode-signup');
  const setMode=next=>{mode=next;const signup=mode==='signup';title.textContent=signup?'Create your CodeVenjar ID':'Login to CodeVenjar';nameField.classList.toggle('hidden',!signup);roleField.classList.toggle('hidden',!signup);document.querySelector('#auth-name').required=signup;submitButton.textContent=signup?'Create CodeVenjar ID':'Login';loginButton.className=signup?'secondary':'primary';signupButton.className=signup?'primary':'secondary';};
  loginButton.onclick=()=>setMode('login');signupButton.onclick=()=>setMode('signup');setMode('login');
  const emailEl=document.querySelector('#auth-email'),passwordEl=document.querySelector('#auth-password'),nameEl=document.querySelector('#auth-name'),roleEl=document.querySelector('#auth-role'),msg=document.querySelector('#auth-message');
  const show=(text,ok=false)=>{msg.classList.remove('hidden');msg.innerHTML=ok?`<strong>${esc(text)}</strong>`:esc(text)};
  const goDemo=(email,password,name,role,action)=>{
    const cleanEmail=email.trim(),cleanName=name.trim();
    if(!cleanEmail){show('Email is required.');emailEl.focus();return;}
    if(password.length<6){show('Password must contain at least 6 characters.');passwordEl.focus();return;}
    if(action==='signup'){
      if(!cleanName){show('Full name is required to create your ID.');nameEl.focus();return;}
      if(demoAuth[cleanEmail.toLowerCase()]){show('This ID already exists. Select Login.');return;}
      const learnerId=`CV-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;demoAuth[cleanEmail.toLowerCase()]={email:cleanEmail,password,name:cleanName,role,learnerId};saveDemoAuth();show('ID created successfully. Select Login and use the same email and password.',true);setMode('login');return;
    }
    const account=demoAuth[cleanEmail.toLowerCase()];if(!account||account.password!==password){show('Invalid email or password. Create your ID first.');return;}
    state.demo=true;state.ready=true;state.role=account.role;state.profile={full_name:account.name,email:account.email,role:account.role,learner_id:account.learnerId};state.plan=state.plan||planFor();saveDemo();toast('Login successful');render();
  };
  form.onsubmit=async event=>{event.preventDefault();const email=emailEl.value.trim(),password=passwordEl.value,name=nameEl.value.trim(),role=roleEl.value;
    if(!db){goDemo(email,password,name,role,mode);return;}
    if(!email){show('Enter your email.');return;}if(password.length<6){show('Password must contain at least 6 characters.');return;}if(mode==='signup'&&!name){show('Enter your full name.');return;}
    show('Connecting to CodeVenjar database…');const result=mode==='signup'?await db.auth.signUp({email,password,options:{data:{full_name:name,role}}}):await db.auth.signInWithPassword({email,password});if(result.error){show(result.error.message);return;}if(result.data.session){state.session=result.data.session;state.user=result.data.user;state.role=role;if(mode==='signup')await db.from('profiles').upsert({id:state.user.id,full_name:name,role,learner_id:userId()});await loadData();await logEvent(mode==='signup'?'Create ID':'Login','User logged in',email);}else show('ID created. Confirm your email, then select Login.',true);
  };
  document.querySelector('#demo-mode').onclick=()=>{setMode('signup');nameEl.value='';show('Local demo: create an ID with name, email and password.');};
};
setInterval(updateClock,1000);
if(state.ready && !state.user && !state.demo) render();
